const http = require('http');
const { Pool } = require('pg');

const pool = new Pool({ connectionString: process.env.DATABASE_URL });

const MAX_BODY_SIZE = 1024 * 1024; // 1 MB

class QuerySerializer {
  constructor(options = {}) {
    this.escapeIdentifier = options.escapeIdentifier || this._defaultEscapeIdentifier;
    this.parameterize = true;
    this._cache = new Map();
  }

  _defaultEscapeIdentifier(identifier) {
    return '"' + identifier.replace(/"/g, '""') + '"';
  }

  serialize(queryDescriptor) {
    const cacheKey = this._computeCacheKey(queryDescriptor);
    if (this._cache.has(cacheKey)) {
      return this._cache.get(cacheKey);
    }
    const result = this._buildQuery(queryDescriptor);
    this._cache.set(cacheKey, result);
    return result;
  }

  _computeCacheKey(descriptor) {
    return JSON.stringify({
      table: descriptor.table,
      columns: descriptor.columns,
      filterKeys: descriptor.filters ? Object.keys(descriptor.filters) : []
    });
  }

  _buildQuery(descriptor) {
    const { table, columns, filters, orderBy } = descriptor;
    const escapedTable = this.escapeIdentifier(table);
    const escapedColumns = columns.map(c => this.escapeIdentifier(c)).join(', ');

    let sql = `SELECT ${escapedColumns} FROM ${escapedTable}`;
    const values = [];

    if (filters && Object.keys(filters).length > 0) {
      const conditions = [];
      for (const [key, value] of Object.entries(filters)) {
        values.push(value);
        conditions.push(`${this.escapeIdentifier(key)} = $${values.length}`);
      }
      sql += ' WHERE ' + conditions.join(' AND ');
    }

    if (orderBy) {
      sql += ` ORDER BY ${this.escapeIdentifier(orderBy.column)}`;
      sql += orderBy.direction === 'DESC' ? ' DESC' : ' ASC';
    }

    return { sql, values };
  }
}

class AppServer {
  constructor() {
    this.serializer = new QuerySerializer({ parameterize: true });
    this.connections = new Set();
    this.isShuttingDown = false;
    this.server = null;
  }

  start(port = 3000) {
    this.server = http.createServer((req, res) => this._handleRequest(req, res));
    this.server.on('connection', (conn) => {
      this.connections.add(conn);
      conn.on('close', () => this.connections.delete(conn));
    });
    this.server.listen(port, () => console.log(`Listening on ${port}`));
    this._setupGracefulShutdown();
  }

  _setupGracefulShutdown() {
    const shutdown = async (signal) => {
      console.log(`Received ${signal}, starting graceful shutdown...`);
      this.isShuttingDown = true;
      this.server.close();
      for (const conn of this.connections) {
        conn.destroy();
      }
      await pool.end();
      console.log('Shutdown complete');
      process.exit(0);
    };
    process.on('SIGTERM', () => shutdown('SIGTERM'));
    process.on('SIGINT', () => shutdown('SIGINT'));
  }

  async _handleRequest(req, res) {
    if (this.isShuttingDown) {
      res.writeHead(503);
      res.end('Service Unavailable');
      return;
    }

    if (req.method === 'POST' && req.url === '/api/query') {
      let body = '';
      let byteLength = 0;
      let aborted = false;
      req.on('data', chunk => {
        if (aborted) return;
        byteLength += chunk.length;
        if (byteLength > MAX_BODY_SIZE) {
          aborted = true;
          res.writeHead(413);
          res.end(JSON.stringify({ error: 'Payload too large' }));
          req.destroy();
          return;
        }
        body += chunk;
      });
      req.on('end', async () => {
        if (aborted) return;
        try {
          const descriptor = JSON.parse(body);
          const validated = this._validateDescriptor(descriptor);
          if (!validated.valid) {
            res.writeHead(400);
            res.end(JSON.stringify({ error: validated.error }));
            return;
          }
          const { sql, values } = this.serializer.serialize(descriptor);
          const result = await pool.query(sql, values);
          res.writeHead(200, { 'Content-Type': 'application/json' });
          res.end(JSON.stringify(result.rows));
        } catch (err) {
          res.writeHead(500);
          res.end(JSON.stringify({ error: 'Internal server error' }));
        }
      });
    } else {
      res.writeHead(404);
      res.end('Not Found');
    }
  }

  _validateDescriptor(descriptor) {
    if (!descriptor.table || typeof descriptor.table !== 'string') {
      return { valid: false, error: 'Invalid table name' };
    }
    if (!Array.isArray(descriptor.columns) || descriptor.columns.length === 0) {
      return { valid: false, error: 'Columns must be a non-empty array' };
    }
    if (!/^[a-zA-Z_][a-zA-Z0-9_]*$/.test(descriptor.table)) {
      return { valid: false, error: 'Table name contains invalid characters' };
    }
    for (const col of descriptor.columns) {
      if (!/^[a-zA-Z_][a-zA-Z0-9_]*$/.test(col)) {
        return { valid: false, error: 'Column name contains invalid characters' };
      }
    }
    if (descriptor.filters) {
      for (const key of Object.keys(descriptor.filters)) {
        if (!/^[a-zA-Z_][a-zA-Z0-9_]*$/.test(key)) {
          return { valid: false, error: 'Filter key contains invalid characters' };
        }
      }
    }
    if (descriptor.orderBy) {
      if (!/^[a-zA-Z_][a-zA-Z0-9_]*$/.test(descriptor.orderBy.column)) {
        return { valid: false, error: 'Order column contains invalid characters' };
      }
    }
    return { valid: true };
  }
}

const app = new AppServer();
app.start(process.env.PORT || 3000);

module.exports = { AppServer, QuerySerializer };
